pub type Message = enum {
  Text(content: Str),
  Image(url: Str),
  File(name: Str, size: Int),
}

fn describe(msg: &Message) -> Str {
  match msg {
    Text(content) => { return "Text: " + content; }
    Image(url) => { return "Image from: " + url; }
    File(name, size) => { return "File: " + name + " (" + size + " bytes)"; }
  }
}

fn main() -> Int {
  let m1 = Message.Text("Hello");
  let m2 = Message.Image("photo.png");
  let m3 = Message.File("doc.txt", 1024);
  return m1.describe().len() + m2.describe().len() + m3.describe().len();
}
